"""Separate report fields and contracts; no composite reliability score."""
from common import *

def blank(ds,model,pair,design,contract):
 return {'dataset':ds,'model':model,'pair':pair,'design':design,'local_observable_gap':np.nan,'local_simultaneous_low':np.nan,'local_simultaneous_high':np.nan,'ranking_gap':np.nan,'ranking_simultaneous_low':np.nan,'ranking_simultaneous_high':np.nan,'ranking_endpoint':'NA','ranking_unit':'examination','influence_beyond_count':np.nan,'influence_simultaneous_low':np.nan,'influence_simultaneous_high':np.nan,'fixed_count_association':np.nan,'fixed_count_simultaneous_low':np.nan,'fixed_count_simultaneous_high':np.nan,'perturbation_stability':'NA','information_contract':contract,'claim_eligibility':'no_positive_claim','aggregation':'mean within examination; mean across examinations','reason_for_NA':''}

def main():
 cross=pd.read_csv(P/'cross_arch_shared_disjoint_intervals.csv');infl=pd.read_csv(OUT/'acquired_only_summary.csv');st=pd.read_csv(P/'acquired_only_stability.csv');hist=pd.read_csv(OUT/'reproduced_architecture_headlines.csv');rows=[]
 for (ds,pair),g in cross.groupby(['dataset','pair']):
  r=blank(ds,'',pair,'cross_arch_phase','target-derived evaluation support; acquired-phase estimator preprocessing');v=g.set_index('endpoint');a=v.loc['observable_gap'];b=v.loc['fixed_reference_ranking']
  r.update(local_observable_gap=a.delta,local_simultaneous_low=a.simultaneous_low,local_simultaneous_high=a.simultaneous_high,ranking_gap=b.delta,ranking_simultaneous_low=b.simultaneous_low,ranking_simultaneous_high=b.simultaneous_high,ranking_endpoint='unchanged reference A MAE',claim_eligibility='ranking-supported' if b.simultaneous_low>0 else ('phenomenon-only' if a.simultaneous_low>0 else 'no_positive_claim'),reason_for_NA='No cross-architecture finite-response experiment was registered; influence and stability fields are NA, not borrowed from within-model probes.');rows.append(r)
 for (ds,model),g in infl.groupby(['dataset','model']):
  r=blank(ds,model,'','acquired_influence','acquired-only mask, scale and finite-response computation; target used only for evaluation');v=g.set_index('endpoint');a=v.loc['beyond_count'];b=v.loc['fixed_count'];q=st[(st.dataset==ds)&(st.model==model)];passed=(q.status=='PASS').all()
  r.update(influence_beyond_count=a.estimate,influence_simultaneous_low=a.simultaneous_low,influence_simultaneous_high=a.simultaneous_high,fixed_count_association=b.estimate,fixed_count_simultaneous_low=b.simultaneous_low,fixed_count_simultaneous_high=b.simultaneous_high,perturbation_stability='PASS' if passed else 'FAIL',claim_eligibility='influence-eligible' if passed and a.simultaneous_low>0 else 'influence-ineligible',aggregation='pooled contexts/planes; examination-cluster bootstrap; fixed count adjusts geometry and examination',reason_for_NA='This probe does not create a phase shared/disjoint ranking contrast; local/ranking gaps are NA. Original six-stratum aggregate stability gate is NA.');rows.append(r)
 for v in hist.itertuples():
  r=blank(v.dataset,v.model,'','historical_same_model_TTA','target-derived evaluation support; historical acquired-phase wrappers');r.update(local_observable_gap=v.local_gap,local_simultaneous_low=v.local_sim_low,local_simultaneous_high=v.local_sim_high,ranking_gap=v.ranking_gap,ranking_simultaneous_low=v.ranking_sim_low,ranking_simultaneous_high=v.ranking_sim_high,ranking_endpoint='condition-specific paired MAE',claim_eligibility='ranking-supported' if v.ranking_sim_low>0 else 'phenomenon-only',aggregation='local: mean/mean fastMRI, median/median IXI; ranking: examination medians',reason_for_NA='Historical influence uses a different context grid/contract; not merged into this TTA row.');rows.append(r)
 df=pd.DataFrame(rows);df.to_csv(P/'mira_report_cards.csv',index=False);write(P/'mira_report_card_schema.json',{'fields':list(df.columns),'designs':df.design.unique().tolist(),'no_composite_scalar':True,'NA':'Not measured or not defined in this design; never replaced by zero or borrowed across contracts.','eligibility':'Influence eligibility requires existing per-stratum stability criterion plus positive simultaneous beyond-count association. Ranking support refers only to its named endpoint; it does not certify deployment.'})
 print('MIRA report cards',len(df))
if __name__=='__main__':main()
